import os
import hashlib
import time
import datetime
import sys
from typing import List

class GitObject:
    def __init__(self, type: str, data: bytes):
        self.type = type
        self.data = data

    def serialize(self) -> bytes:
        return f"{self.type} {len(self.data)}\0".encode() + self.data

    @classmethod
    def deserialize(cls, data: bytes) -> 'GitObject':
        space_pos = data.find(b' ')
        type = data[:space_pos].decode()
        null_pos = data.find(b'\0')
        size = int(data[space_pos + 1:null_pos].decode())
        content = data[null_pos + 1:null_pos + 1 + size]
        return cls(type, content)

class Blob(GitObject):
    def __init__(self, data: bytes):
        super().__init__('blob', data)

class Tree(GitObject):
    def __init__(self, entries: List[tuple]):
        self.entries = entries
        data = b''
        for entry in entries:
            data += f"{entry[0].decode()} {entry[1].decode()} {entry[2]}\n".encode()
        super().__init__('tree', data)

class Commit(GitObject):
    def __init__(self, tree: bytes, parent: bytes, author: str, message: str):
        self.tree = tree
        self.parent = parent
        self.author = author
        self.message = message
        data = f"tree {tree.decode()}\nparent {parent.decode()}\nauthor {author}\n\n{message}".encode()
        super().__init__('commit', data)

class GitRepository:
    def __init__(self, path: str = '.'):
        self.path = path
        self.objects = {}

    def init(self):
        os.makedirs(os.path.join(self.path, '.git'), exist_ok=True)
        os.makedirs(os.path.join(self.path, '.git', 'objects'), exist_ok=True)

    def add(self, file_path: str):
        with open(file_path, 'rb') as f:
            data = f.read()
        blob = Blob(data)
        object_id = hashlib.sha1(blob.serialize()).hexdigest()
        self.save_object(blob, object_id)
        return object_id

    def save_object(self, obj: GitObject, object_id: str):
        with open(os.path.join(self.path, '.git', 'objects', object_id[:2], object_id[2:]), 'wb') as f:
            f.write(obj.serialize())
        self.objects[object_id] = obj

    def load_object(self, object_id: str) -> GitObject:
        if object_id in self.objects:
            return self.objects[object_id]
        with open(os.path.join(self.path, '.git', 'objects', object_id[:2], object_id[2:]), 'rb') as f:
            data = f.read()
        obj = GitObject.deserialize(data)
        self.objects[object_id] = obj
