            print(f"Message: {commit.message}")
            print()
            if commit.parent:
                commit_id = commit.parent.decode()
                commit = self.load_object(commit_id)
            else:
                break

    def diff(self, commit_id1: str, commit_id2: str):
        commit1 = self.load_object(commit_id1)
        commit2 = self.load_object(commit_id2)
        tree1 = self.load_object(commit1.tree.decode())
