            commit_id = f.read()
        commit = self.load_object(commit_id)
        tree = self.load_object(commit.tree.decode())
        for entry in tree.entries:
            with open(entry[0].decode(), 'wb') as f:
                f.write(self.load_object(entry[2]).data)

