import pickle
import os
import threading
import time
import uuid

class RedisClone:
    def __init__(self):
        self.data = {}
        self.expires = {}
        self.lock = threading.Lock()
        self.subscribers = {}
        self.snapshot_interval = 60  # 1 minute
        self.snapshot_thread = threading.Thread(target=self.take_snapshot)
        self.snapshot_thread.daemon = True
        self.snapshot_thread.start()

    def get(self, key):
        with self.lock:
            if key in self.expires and self.expires[key] < time.time():
                del self.data[key]
                del self.expires[key]
                return None
            return self.data.get(key)

    def set(self, key, value):
        with self.lock:
            self.data[key] = value
            if key in self.expires:
                del self.expires[key]

    def delete(self, key):
        with self.lock:
            if key in self.data:
                del self.data[key]
            if key in self.expires:
                del self.expires[key]

    def expire(self, key, seconds):
        with self.lock:
            self.expires[key] = time.time() + seconds

    def lpush(self, key, value):
        with self.lock:
            if key not in self.data:
                self.data[key] = []
            self.data[key].insert(0, value)

    def rpush(self, key, value):
        with self.lock:
            if key not in self.data:
                self.data[key] = []
            self.data[key].append(value)

    def lpop(self, key):
        with self.lock:
            if key in self.data and self.data[key]:
                return self.data[key].pop(0)
            return None

    def subscribe(self, channel, callback):
        with self.lock:
            if channel not in self.subscribers:
                self.subscribers[channel] = []
            self.subscribers[channel].append(callback)

    def publish(self, channel, message):
        with self.lock:
            if channel in self.subscribers:
                for callback in self.subscribers[channel]:
                    callback(message)

    def take_snapshot(self):
        while True:
            with self.lock:
                with open('snapshot.rdb', 'wb') as f:
                    pickle.dump(self.data, f)
                    pickle.dump(self.expires, f)
            time.sleep(self.snapshot_interval)

    def load_snapshot(self):
        if os.path.exists('snapshot.rdb'):
            with open('snapshot.rdb', 'rb') as f:
                self.data = pickle.load(f)
                self.expires = pickle.load(f)

# Example usage
redis = RedisClone()
redis.load_snapshot()

def callback(message):
    print(f'Received message: {message}')

redis.subscribe('channel', callback)
redis.publish('channel', 'Hello, world!')
print(redis.get('key'))  # None
redis.set('key', 'value')
print(redis.get('key'))  # 'value'
redis.expire('key', 10)
time.sleep(11)
print(redis.get('key'))  # None
redis.lpush('list', 'value1')
redis.rpush('list', 'value2')
print(redis.lpop('list'))  # 'value1'
print(redis.lpop('list'))  # 'value2'
```

