import hashlib
import time
import threading
import random

# HealthCheck class for checking server health
class HealthCheck:
    def __init__(self, url):
        self.url = url
        self.healthy = True

    def check(self):
        # Simulate a health check, replace with actual HTTP request
        self.healthy = random.random() > 0.5  # 50% chance of being healthy
        return self.healthy

# Server class for load balancing
class Server:
    def __init__(self, url, weight=1):
        self.url = url
        self.weight = weight
        self.connections = 0
        self.health_check = HealthCheck(url)

    def is_healthy(self):
        return self.health_check.check()

# LoadBalancer class for distributing traffic
class LoadBalancer:
    def __init__(self, algorithm='round-robin', servers=None):
        self.algorithm = algorithm
        self.servers = servers if servers else []
        self.current_server_index = 0
        self.server_map = {}

    def add_server(self, server):
        self.servers.append(server)
        if self.algorithm == 'consistent-hashing':
            # Calculate hash for consistent hashing
            hash_value = self._hash(server.url)
            if hash_value not in self.server_map:
                self.server_map[hash_value] = server

    def remove_server(self, server):
        if server in self.servers:
            self.servers.remove(server)
            if self.algorithm == 'consistent-hashing':
                # Remove hash for consistent hashing
                hash_value = self._hash(server.url)
                if hash_value in self.server_map:
                    del self.server_map[hash_value]

    def _hash(self, url):
        return int(hashlib.md5(url.encode()).hexdigest(), 16)

    def get_server(self):
        if self.algorithm == 'round-robin':
            return self._round_robin()
        elif self.algorithm == 'least-connections':
            return self._least_connections()
        elif self.algorithm == 'weighted':
            return self._weighted()
        elif self.algorithm == 'consistent-hashing':
            return self._consistent_hashing()

    def _round_robin(self):
        server = self.servers[self.current_server_index]
        self.current_server_index = (self.current_server_index + 1) % len(self.servers)
        return server

    def _least_connections(self):
        least_connected_server = min([s for s in self.servers if s.is_healthy()], key=lambda s: s.connections)
        least_connected_server.connections += 1
        return least_connected_server

    def _weighted(self):
        weights = [s.weight for s in self.servers if s.is_healthy()]
        total_weight = sum(weights)
        random_weight = random.random() * total_weight
        cumulative_weight = 0
        for i, weight in enumerate(weights):
            cumulative_weight += weight
            if random_weight <= cumulative_weight:
                return self.servers[i]

    def _consistent_hashing(self):
        client_hash = int(hashlib.md5('client'.encode()).hexdigest(), 16)
        sorted_servers = sorted(self.server_map.items())
        for hash_value, server in sorted_servers:
            if client_hash <= hash_value:
                return server
        return sorted_servers[0][1]

# Example usage
if __name__ == '__main__':
    load_balancer = LoadBalancer(algorithm='consistent-hashing')

    servers = [
        Server('http://server1.com', weight=3),
        Server('http://server2.com', weight=2),
        Server('http://server3.com', weight=1)
    ]

    for server in servers:
        load_balancer.add_server(server)

    def request_server():
        server = load_balancer.get_server()
        print(f"Requesting {server.url}")
        server.connections -= 1  # Decrement connections after request

    threads = []
    for _ in range(10):
        thread = threading.Thread(target=request_server)
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()
```

**Code Explanation:**

1. **HealthCheck Class:** This class is used to simulate health checks for each server. It has a method `check` which returns `True` if the server is healthy and `False` otherwise.
2. **Server Class:** This class represents each server in the load balancer. It has a `url`, `weight`, `connections`, and a `health_check` object.
3. **LoadBalancer Class:** This class is the core of the load balancer. It has methods to add and remove servers, and to get the next server based on the chosen algorithm.
4. **Algorithms:**
   * **Round-Robin:** Each request is sent to the next server in the list.
   * **Least-Connections:** Each request is sent to the server with the least number of active connections.
   * **Weighted:** Each request is sent to a server based on its weight.
   * **Consistent-Hashing:** Each request is sent to a server based on a hash of the client's IP address.
5. **Example Usage:** An example usage of the load balancer is provided in the `if __name__ == '__main__':` block. It creates a load balancer with three servers, and then simulates 10 requests to the load balancer.

**Real-Time Collaborative Text Editor using Operational Transformation (OT) with WebSocket Server**

This implementation uses Node.js, WebSocket, and JavaScript to create a real-time collaborative text editor. We'll use the Operational Transformation (OT) algorithm to manage concurrent updates.

**Server-side Code (Node.js)**
```javascript
// Import required modules
const WebSocket = require('ws');
const wss = new WebSocket.Server({ port: 8080 });

// Initialize a map to store client connections
const clients = new Map();

// Initialize a shared document
let document = '';

// Function to apply an operation to the document
function applyOperation(operation) {
  switch (operation.type) {
    case 'insert':
      document = document.substring(0, operation.position) + operation.text + document.substring(operation.position);
      break;
    case 'delete':
      document = document.substring(0, operation.position) + document.substring(operation.position + operation.length);
      break;
  }
}

// Function to transform an operation against another operation
function transform(operation1, operation2) {
  if (operation1.type === 'insert' && operation2.type === 'insert') {
    if (operation1.position > operation2.position) {
      operation1.position += operation2.text.length;
    }
  } else if (operation1.type === 'insert' && operation2.type === 'delete') {
    if (operation1.position > operation2.position) {
      operation1.position -= operation2.length;
    }
  } else if (operation1.type === 'delete' && operation2.type === 'insert') {
    if (operation1.position > operation2.position) {
      operation1.position += operation2.text.length;
    }
  } else if (operation1.type === 'delete' && operation2.type === 'delete') {
    if (operation1.position > operation2.position) {
      operation1.position -= operation2.length;
    }
  }
  return operation1;
}

// Handle WebSocket connections
wss.on('connection', (ws) => {
  // Store the client connection
  clients.set(ws, { document: document });

  // Handle incoming messages
  ws.on('message', (message) => {
    const operation = JSON.parse(message);
    applyOperation(operation);
    for (const [client, clientData] of clients) {
      if (client !== ws) {
        client.send(JSON.stringify(operation));
      }
    }
  });

  // Handle client disconnection
  ws.on('close', () => {
    clients.delete(ws);
  });
});

console.log('WebSocket server listening on port 8080');
```

**Client-side Code (JavaScript)**
```javascript
// Establish a WebSocket connection
const socket = new WebSocket('ws://localhost:8080');

// Initialize the editor
const editor = document.getElementById('editor');

// Initialize the local document
let localDocument = '';

// Handle incoming messages
socket.onmessage = (event) => {
  const operation = JSON.parse(event.data);
  // Transform the operation against local operations
  const transformedOperation = transform(operation, localDocument);
  applyOperation(transformedOperation);
  editor.value = localDocument;
};

// Handle user input
editor.addEventListener('input', (event) => {
  const userInput = event.target.value;
  const operation = {
    type: 'insert',
    position: editor.selectionStart,
    text: userInput.substring(localDocument.length),
  };
  localDocument = userInput;
  socket.send(JSON.stringify(operation));
});

// Handle delete event
editor.addEventListener('keydown', (event) => {
  if (event.key === 'Backspace') {
    const operation = {
      type: 'delete',
      position: editor.selectionStart,
      length: 1,
    };
    localDocument = localDocument.substring(0, editor.selectionStart - 1) + localDocument.substring(editor.selectionStart);
    socket.send(JSON.stringify(operation));
  }
});
