from typing import List, Tuple

# Constants
PAGE_SIZE = 4096
NODE_SIZE = PAGE_SIZE // 2
KEY_SIZE = 8
VALUE_SIZE = 16
WAL_MAX_SIZE = 1024 * 1024 * 1024

# Data Structures
class BPlusTreeNode:
    def __init__(self, is_leaf: bool, page_id: int):
        self.is_leaf = is_leaf
        self.page_id = page_id
        self.keys = []
        self.children = []
        self.next = None

class BPlusTree:
    def __init__(self):
        self.root = BPlusTreeNode(True, 0)
        self.page_id = 0

    def insert(self, key: int, value: int):
        self.root = self._insert(self.root, key, value)

    def _insert(self, node: BPlusTreeNode, key: int, value: int):
        if node.is_leaf:
            node.keys.append(key)
            node.children.append(value)
            node.keys.sort()
            if len(node.keys) > NODE_SIZE:
                new_node = BPlusTreeNode(True, self.page_id)
                self.page_id += 1
                new_node.keys = node.keys[NODE_SIZE:]
                new_node.children = node.children[NODE_SIZE:]
                node.keys = node.keys[:NODE_SIZE]
                node.children = node.children[:NODE_SIZE]
                new_node.next = node.next
                node.next = new_node
                return node
            return node
        else:
            index = 0
            while index < len(node.keys) and node.keys[index] < key:
                index += 1
            if len(node.children) > index:
                node.children[index] = self._insert(node.children[index], key, value)
            return node

class BPlusTreeIndex:
    def __init__(self):
        self.bplus_tree = BPlusTree()

    def insert(self, key: int, value: int):
        self.bplus_tree.insert(key, value)

class WAL:
    def __init__(self):
        self.log = []
        self.lock = threading.Lock()

    def write(self, key: int, value: int):
        with self.lock:
            self.log.append((key, value))

    def flush(self):
        with self.lock:
            logs = self.log[:]
            self.log = []
        return logs

class BufferPool:
    def __init__(self):
        self.pages = {}
        self.lock = threading.Lock()

    def get_page(self, page_id: int):
        with self.lock:
            if page_id not in self.pages:
                self.pages[page_id] = b'\x00' * PAGE_SIZE
            return self.pages[page_id]

    def write_page(self, page_id: int, data: bytes):
        with self.lock:
            self.pages[page_id] = data

class MVCC:
    def __init__(self):
        self.transactions = {}

    def start_transaction(self, transaction_id: int):
        self.transactions[transaction_id] = {}

    def commit_transaction(self, transaction_id: int):
        del self.transactions[transaction_id]

    def write(self, transaction_id: int, key: int, value: int):
        self.transactions[transaction_id][key] = value

class SQLQueryExecutor:
    def __init__(self, bplus_tree_index: BPlusTreeIndex, mvcc: MVCC):
        self.bplus_tree_index = bplus_tree_index
        self.mvcc = mvcc

    def execute_insert(self, key: int, value: int):
        self.bplus_tree_index.insert(key, value)

    def execute_select(self, key: int):
        # This is a simplified implementation and doesn't support MVCC
        # In a real implementation, we would need to consider the current transaction and the version of the key
        return self.bplus_tree_index.bplus_tree.root.keys[0]

class DatabaseStorageEngine:
    def __init__(self):
        self.bplus_tree_index = BPlusTreeIndex()
        self.wal = WAL()
        self.buffer_pool = BufferPool()
        self.mvcc = MVCC()
        self.sql_query_executor = SQLQueryExecutor(self.bplus_tree_index, self.mvcc)

    def insert(self, key: int, value: int):
        self.wal.write(key, value)
        self.sql_query_executor.execute_insert(key, value)
        self.mvcc.write(0, key, value)

    def select(self, key: int):
        return self.sql_query_executor.execute_select(key)

# Usage
