Below is a simplified implementation of an infrastructure-as-code tool in Python, inspired by Terraform. This tool manages resources with a state file, plans changes, and applies them idempotently.

**infrastructure_as_code.py**
```python
import json
import os
import shutil
import tempfile

class Resource:
    def __init__(self, name, type, properties):
        self.name = name
        self.type = type
        self.properties = properties

class State:
    def __init__(self, state_file):
        self.state_file = state_file
        self.resources = {}
        self.load()

    def load(self):
        if os.path.exists(self.state_file):
            with open(self.state_file, 'r') as f:
                self.resources = json.load(f)

    def save(self):
        with open(self.state_file, 'w') as f:
            json.dump(self.resources, f)

    def get_resource(self, name):
        return self.resources.get(name)

    def add_resource(self, resource):
        self.resources[resource.name] = {
            'type': resource.type,
            'properties': resource.properties
        }

    def update_resource(self, name, properties):
        if name in self.resources:
            self.resources[name]['properties'] = properties

    def delete_resource(self, name):
        if name in self.resources:
            del self.resources[name]

class Planner:
    def __init__(self, state):
        self.state = state

    def plan(self, resources):
        planned_resources = []
        for resource in resources:
            existing_resource = self.state.get_resource(resource.name)
            if existing_resource:
                if existing_resource['type'] != resource.type or existing_resource['properties'] != resource.properties:
                    planned_resources.append({
                        'action': 'update',
                        'resource': resource
                    })
            else:
                planned_resources.append({
                    'action': 'create',
                    'resource': resource
                })
        return planned_resources

class Applier:
    def __init__(self, state):
        self.state = state

    def apply(self, planned_resources):
        for planned_resource in planned_resources:
            if planned_resource['action'] == 'create':
                self.create_resource(planned_resource['resource'])
            elif planned_resource['action'] == 'update':
                self.update_resource(planned_resource['resource'])
            elif planned_resource['action'] == 'delete':
                self.delete_resource(planned_resource['resource'])

    def create_resource(self, resource):
        print(f"Creating resource {resource.name} of type {resource.type} with properties {resource.properties}")
        self.state.add_resource(resource)

    def update_resource(self, resource):
        print(f"Updating resource {resource.name} with properties {resource.properties}")
        self.state.update_resource(resource.name, resource.properties)

    def delete_resource(self, resource):
        print(f"Deleting resource {resource.name}")
        self.state.delete_resource(resource.name)

def main():
    state_file = 'state.json'
    state = State(state_file)

    resources = [
        Resource('example', 'example_type', {'property1': 'value1', 'property2': 'value2'}),
        Resource('example2', 'example_type2', {'property3': 'value3', 'property4': 'value4'})
    ]

    planner = Planner(state)
    planned_resources = planner.plan(resources)

    applier = Applier(state)
    applier.apply(planned_resources)

    state.save()

if __name__ == '__main__':
    main()
```

### Example Usage:
1. Create a `state.json` file in the same directory as the script.
2. Run the script using `python infrastructure_as_code.py`.
3. The script will create resources defined in the `resources` list in the `main` function.
4. Modify the `resources` list to update or delete resources.
5. Run the script again to apply the changes.

**Note:** This is a simplified example and does not handle real-world resources or error handling. It is meant to demonstrate the basic concept of an infrastructure-as-code tool.

### State File Format:
The state file is a JSON file that stores the current state of the resources. The format is as follows:
```json
{
    "resource_name": {
        "type": "resource_type",
        "properties": {
            "property1": "value1",
            "property2": "value2"
        }
    }
}
```
This format allows for easy modification and extension of the state file to accommodate different types of resources and properties.

Below is an example of a simple compiler written in Python that supports variables, functions, if/else, and loops. This compiler generates LLVM IR.

```python
# compiler.py
import re
from llvmlite import ir, binding
from llvmlite.binding import llvm

# Initialize LLVM
llvm.initialize()
llvm.initialize_all_targets()
llvm.initialize_all_asmprinters()

class Token:
    def __init__(self, type, value):
        self.type = type
        self.value = value

    def __repr__(self):
        return f'Token({self.type}, {self.value})'

class Lexer:
    def __init__(self, code):
        self.code = code
        self.pos = 0
        self.tokens = []

    def tokenize(self):
        keywords = ['if', 'else', 'while', 'def']
        identifiers = ['[a-zA-Z_][a-zA-Z0-9_]*']
        operators = ['+', '-', '*', '/', '<', '>', '=']
        literals = ['[0-9]+']

        while self.pos < len(self.code):
            if self.code[self.pos].isspace():
                self.pos += 1
            elif self.code[self.pos].isalpha() or self.code[self.pos] == '_':
                match = re.match('|'.join(identifiers), self.code[self.pos:])
                if match:
                    token = Token('IDENTIFIER', match.group())
                    self.tokens.append(token)
                    self.pos += len(match.group())
                else:
                    raise Exception('Invalid identifier')
            elif self.code[self.pos].isdigit():
                match = re.match('|'.join(literals), self.code[self.pos:])
                if match:
                    token = Token('LITERAL', match.group())
                    self.tokens.append(token)
                    self.pos += len(match.group())
                else:
                    raise Exception('Invalid literal')
            elif self.code[self.pos] in '+-*/<>=;':
                token = Token('OPERATOR', self.code[self.pos])
                self.tokens.append(token)
                self.pos += 1
            elif self.code[self.pos] == '{':
                token = Token('BLOCK_START', self.code[self.pos])
                self.tokens.append(token)
                self.pos += 1
            elif self.code[self.pos] == '}':
                token = Token('BLOCK_END', self.code[self.pos])
                self.tokens.append(token)
                self.pos += 1
            else:
                raise Exception('Invalid character')

        self.tokens.append(Token('EOF', 'EOF'))
        return self.tokens

class Parser:
    def __init__(self, tokens):
        self.tokens = tokens
        self.pos = 0

    def parse(self):
        ast = []
        while self.pos < len(self.tokens):
            if self.tokens[self.pos].type == 'IDENTIFIER' and self.tokens[self.pos + 1].type == 'OPERATOR' and self.tokens[self.pos + 1].value == '=':
                # Assignment statement
                ast.append({'type': 'ASSIGN', 'name': self.tokens[self.pos].value, 'value': self.parse_expression()})
            elif self.tokens[self.pos].type == 'IDENTIFIER' and self.tokens[self.pos + 1].type == 'BLOCK_START':
                # Function definition
                ast.append({'type': 'FUNCTION', 'name': self.tokens[self.pos].value, 'body': self.parse_block()})
            elif self.tokens[self.pos].type == 'IF':
                # If statement
                ast.append({'type': 'IF', 'condition': self.parse_expression(), 'body': self.parse_block(), 'else_body': self.parse_else_block()})
            elif self.tokens[self.pos].type == 'WHILE':
                # While loop
                ast.append({'type': 'WHILE', 'condition': self.parse_expression(), 'body': self.parse_block()})
            self.pos += 1
        return ast

    def parse_expression(self):
        # Simple expression parser for now
        # Supports only literals and identifiers
        if self.tokens[self.pos].type == 'LITERAL':
            value = int(self.tokens[self.pos].value)
            self.pos += 1
            return value
        elif self.tokens[self.pos].type == 'IDENTIFIER':
            name = self.tokens[self.pos].value
            self.pos += 1
            return name

    def parse_block(self):
        block = []
        self.pos += 1  # Skip BLOCK_START
        while self.tokens[self.pos].type != 'BLOCK_END':
            block.append(self.parse_statement())
        self.pos += 1  # Skip BLOCK_END
        return block

    def parse_statement(self):
        if self.tokens[self.pos].type == 'IDENTIFIER' and self.tokens[self.pos + 1].type == 'OPERATOR' and self.tokens[self.pos + 1].value == '=':
            # Assignment statement
            return {'type': 'ASSIGN', 'name': self.tokens[self.pos].value, 'value': self.parse_expression()}
        elif self.tokens[self.pos].type == 'IF':
            # If statement
            return {'type': 'IF', 'condition': self.parse_expression(), 'body': self.parse_block(), 'else_body': self.parse_else_block()}
        elif self.tokens[self.pos].type == 'WHILE':
            # While loop
            return {'type': 'WHILE', 'condition': self.parse_expression(), 'body': self.parse_block()}

    def parse_else_block(self):
        if self.tokens[self.pos].type == 'ELSE':
            self.pos += 1  # Skip ELSE
            return self.parse_block()
        else:
            return []

class CodeGenerator:
    def __init__(self, ast):
        self.module = ir.Module(name='example')
        self.builder = ir.IRBuilder(self.module)

    def generate(self):
        for node in ast:
            if node['type'] == 'ASSIGN':
                self.assign(node['name'], node['value'])
            elif node['type'] == 'FUNCTION':
                self.function(node['name'], node['body'])
            elif node['type'] == 'IF':
                self.if_statement(node['condition'], node['body'], node['else_body'])
            elif node['type'] == 'WHILE':
                self.while_loop(node['condition'], node['body'])

    def assign(self, name, value):
        if isinstance(value, int):
            value = ir.Constant(ir.Int32, value)
        elif isinstance(value, str):
            value = self.module.get_global_variable(name)
        if not self.module.get_global_variable(name):
            var = ir.GlobalVariable(self.module, ir.Int32, name)
            var.initializer = ir.Constant(ir.Int32, 0)
        self.builder.store(value, self.module.get_global_variable(name))

    def function(self, name, body):
        func_type = ir.FunctionType(ir.VoidType(), [])
        func = ir.Function(self.module, func_type, name)
        func_block = func.append_basic_block(name)
        self.builder.position_at_end(func_block)
        for node in body:
            if node['type'] == 'ASSIGN':
                self.assign(node['name'], node['value'])
            elif node['type'] == 'IF':
                self.if_statement(node['condition'], node['body'], node['else_body'])
            elif node['type'] == 'WHILE':
                self.while_loop(node['condition'], node['body'])

    def if_statement(self, condition, body, else_body):
        if condition == 0:
            condition = ir.Constant(ir.Int32, 0)
        else:
            condition = ir.Constant(ir.Int32, 1)
        if_block = self.builder.append_basic_block('if')
        else_block = self.builder.append_basic_block('else')
        self.builder.cbranch(condition, if_block, else_block)
        self.builder.position_at_end(if_block)
        for node in body:
            if node['type'] == 'ASSIGN':
                self.assign(node['name'], node['value'])
            elif node['type'] == 'IF':
                self.if_statement(node['condition'], node['body'], node['else_body'])
            elif node['type'] == 'WHILE':
                self.while_loop(node['condition'], node['body'])
        self.builder.position_at_end(else_block)
        for node in else_body:
            if node['type'] == 'ASSIGN':
                self.assign(node['name'], node['value'])
            elif node['type'] == 'IF':
                self.if_statement(node['condition'], node['body'], node['else_body'])
            elif node['type'] == 'WHILE':
                self.while_loop(node['condition'], node['body'])

    def while_loop(self, condition, body):
        loop_block = self.builder.append_basic_block('while')
        self.builder.branch(loop_block)
        self.builder.position_at_end(loop_block)
        if condition == 0:
            condition = ir.Constant(ir.Int32, 0)
        else:
            condition = ir.Constant(ir.Int32, 1)
        self.builder.cbranch(condition, loop_block, self.builder.block)
        for node in body:
            if node['type'] == 'ASSIGN':
                self.assign(node['name'], node['value'])
            elif node['type'] == 'IF':
                self.if_statement(node['condition'], node['body'], node['else_body'])
            elif node['type'] == 'WHILE':
                self.while_loop(node['condition'], node['body'])

if __name__ == '__main__':
    code = """
    def test() {
        x = 5
        if 1 {
            x = 10
        } else {
            x = 15
        }
        while 1 {
            x = x + 1
        }
    }
    """

    lexer = Lexer(code)
    tokens = lexer.tokenize()
    parser = Parser(tokens)
    ast = parser.parse()

    code_generator = CodeGenerator(ast)
    code_generator.generate()

    print(code_generator.module)
```

