Below is a simplified implementation of a Terraform-like infrastructure-as-code tool in Python. It supports creating and managing resources (in this case, AWS EC2 instances), planning changes, and applying them idempotently.

**Note:** This is a simplified example and does not cover all the features and complexities of Terraform. It's primarily for educational purposes.

```python
import json
import os
import boto3

# Define a resource class
class Resource:
    def __init__(self, name, type, properties):
        self.name = name
        self.type = type
        self.properties = properties

# Define a state class
class State:
    def __init__(self, filename):
        self.filename = filename
        self.resources = []

    def load(self):
        if os.path.exists(self.filename):
            with open(self.filename, 'r') as f:
                data = json.load(f)
                for resource_data in data:
                    resource = Resource(resource_data['name'], resource_data['type'], resource_data['properties'])
                    self.resources.append(resource)

    def save(self):
        data = []
        for resource in self.resources:
            data.append({
                'name': resource.name,
                'type': resource.type,
                'properties': resource.properties
            })
        with open(self.filename, 'w') as f:
            json.dump(data, f, indent=4)

# Define a planner class
class Planner:
    def __init__(self, state):
        self.state = state

    def plan(self, desired_resources):
        plan = []
        for desired_resource in desired_resources:
            existing_resource = next((r for r in self.state.resources if r.name == desired_resource.name and r.type == desired_resource.type), None)
            if existing_resource:
                if existing_resource.properties != desired_resource.properties:
                    plan.append({
                        'action': 'update',
                        'resource': desired_resource
                    })
            else:
                plan.append({
                    'action': 'create',
                    'resource': desired_resource
                })
        return plan

# Define an applier class
class Applier:
    def __init__(self, state):
        self.state = state
        self.ec2 = boto3.client('ec2')

    def create(self, resource):
        if resource.type == 'aws_ec2_instance':
            self.ec2.run_instances(ImageId=resource.properties['image_id'], InstanceType=resource.properties['instance_type'], MinCount=1, MaxCount=1)
            self.state.resources.append(resource)

    def update(self, resource):
        if resource.type == 'aws_ec2_instance':
            # Update the EC2 instance properties (for simplicity, let's assume we're updating the instance type)
            self.ec2.modify_instance_attribute(InstanceId=resource.properties['instance_id'], Attribute='instanceType', Value=resource.properties['instance_type'])
            # Update the resource properties in the state
            for existing_resource in self.state.resources:
                if existing_resource.name == resource.name and existing_resource.type == resource.type:
                    existing_resource.properties = resource.properties

# Define a main function
def main():
    state_filename = 'state.json'
    state = State(state_filename)
    state.load()

    desired_resources = [
        Resource('my-ec2-instance', 'aws_ec2_instance', {'image_id': 'ami-abc123', 'instance_type': 't2.micro', 'instance_id': 'i-12345678'}),
        Resource('my-other-ec2-instance', 'aws_ec2_instance', {'image_id': 'ami-def456', 'instance_type': 't2.micro', 'instance_id': 'i-90123456'})
    ]

    planner = Planner(state)
    plan = planner.plan(desired_resources)
    print('Plan:')
    for action in plan:
        print(f"  {action['action']} {action['resource'].name}")

    applier = Applier(state)
    for action in plan:
        if action['action'] == 'create':
            applier.create(action['resource'])
        elif action['action'] == 'update':
            applier.update(action['resource'])

    state.save()

if __name__ == '__main__':
    main()
```

**Example Use Case:**

1. Create a new file named `state.json` with the following contents:
```json
[
    {
        "name": "my-ec2-instance",
        "type": "aws_ec2_instance",
        "properties": {
            "image_id": "ami-abc123",
            "instance_type": "t2.micro",
            "instance_id": "i-12345678"
        }
    }
]
```
2. Run the `main.py` script.
3. The script will load the state from `state.json`, plan the changes, and apply them.
4. The resulting state will be saved back to `state.json`.

**Note:** This example uses AWS EC2 instances as resources, but you can modify the code to support other types of resources. Additionally, this is a highly simplified example and does not cover all the features and complexities of Terraform.

Here's an example DNS server implementation in Python that supports A, AAAA, CNAME, MX, NS, SOA, and TXT records with zone file parsing and recursive resolution:

```python
# dns_server.py

import socket
import threading
from dns import zone, query, update, rdatatype
from dns.resolver import resolve

# Define a dictionary to store the zone data
zone_data = {}

# Load the zone data from a file
def load_zone_data(file_name):
    with open(file_name, 'r') as f:
        lines = f.readlines()
        for line in lines:
            parts = line.split()
            if len(parts) < 2:
                continue
            name = parts[0]
            type = parts[1]
            data = parts[2:]
            if name not in zone_data:
                zone_data[name] = {}
            zone_data[name][type] = data

# Start the DNS server
def start_dns_server(port=53):
    server_socket = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    server_socket.bind(('', port))

    while True:
        data, addr = server_socket.recvfrom(1024)
        query_data = query.from_wire(data)
        response_data = handle_query(query_data)
        server_socket.sendto(response_data, addr)

# Handle a DNS query
def handle_query(query_data):
    question = query_data.question[0]
    name = question.name.to_text()
    type = question.rdtype

    if type == rdatatype.A:
        # Handle A record query
        return handle_a_record_query(name)

    elif type == rdatatype.AAAA:
        # Handle AAAA record query
        return handle_aaaa_record_query(name)

    elif type == rdatatype.CNAME:
        # Handle CNAME record query
        return handle_cname_record_query(name)

    elif type == rdatatype.MX:
        # Handle MX record query
        return handle_mx_record_query(name)

    elif type == rdatatype.NS:
        # Handle NS record query
        return handle_ns_record_query(name)

    elif type == rdatatype.SOA:
        # Handle SOA record query
        return handle_soa_record_query(name)

    elif type == rdatatype.TXT:
        # Handle TXT record query
        return handle_txt_record_query(name)

    else:
        # Handle unknown record type
        return handle_unknown_record_query(name)

# Handle A record query
def handle_a_record_query(name):
    if name in zone_data and 'A' in zone_data[name]:
        answer = query.answer(name, 'A', zone_data[name]['A'])
        return query.to_wire(answer)
    else:
        # Recursive resolution
        try:
            answers = resolve(name, 'A')
            return query.to_wire(answers)
        except Exception as e:
            return handle_error(e)

# Handle AAAA record query
def handle_aaaa_record_query(name):
    if name in zone_data and 'AAAA' in zone_data[name]:
        answer = query.answer(name, 'AAAA', zone_data[name]['AAAA'])
        return query.to_wire(answer)
    else:
        # Recursive resolution
        try:
            answers = resolve(name, 'AAAA')
            return query.to_wire(answers)
        except Exception as e:
            return handle_error(e)

# Handle CNAME record query
def handle_cname_record_query(name):
    if name in zone_data and 'CNAME' in zone_data[name]:
        answer = query.answer(name, 'CNAME', zone_data[name]['CNAME'])
        return query.to_wire(answer)
    else:
        # Recursive resolution
        try:
            answers = resolve(name, 'CNAME')
            return query.to_wire(answers)
        except Exception as e:
            return handle_error(e)

# Handle MX record query
def handle_mx_record_query(name):
    if name in zone_data and 'MX' in zone_data[name]:
        answer = query.answer(name, 'MX', zone_data[name]['MX'])
        return query.to_wire(answer)
    else:
        # Recursive resolution
        try:
            answers = resolve(name, 'MX')
            return query.to_wire(answers)
        except Exception as e:
            return handle_error(e)

# Handle NS record query
def handle_ns_record_query(name):
    if name in zone_data and 'NS' in zone_data[name]:
        answer = query.answer(name, 'NS', zone_data[name]['NS'])
        return query.to_wire(answer)
    else:
        # Recursive resolution
        try:
            answers = resolve(name, 'NS')
            return query.to_wire(answers)
        except Exception as e:
            return handle_error(e)

# Handle SOA record query
def handle_soa_record_query(name):
    if name in zone_data and 'SOA' in zone_data[name]:
        answer = query.answer(name, 'SOA', zone_data[name]['SOA'])
        return query.to_wire(answer)
    else:
        # Recursive resolution
        try:
            answers = resolve(name, 'SOA')
            return query.to_wire(answers)
        except Exception as e:
            return handle_error(e)

# Handle TXT record query
def handle_txt_record_query(name):
    if name in zone_data and 'TXT' in zone_data[name]:
        answer = query.answer(name, 'TXT', zone_data[name]['TXT'])
        return query.to_wire(answer)
    else:
        # Recursive resolution
        try:
            answers = resolve(name, 'TXT')
            return query.to_wire(answers)
        except Exception as e:
            return handle_error(e)

# Handle unknown record type
def handle_unknown_record_query(name):
    # Recursive resolution
    try:
        answers = resolve(name, 'A')
        return query.to_wire(answers)
    except Exception as e:
        return handle_error(e)

# Handle error
def handle_error(e):
    print(f'Error: {e}')
    return b''

# Load the zone data and start the DNS server
load_zone_data('zone.txt')
start_dns_server()
```

