        else:
            raise Exception(f"Unknown statement type {statement.node_type}")

    def generate_function_definition(self, statement: AstNode) -> str:
        code = f"define void @{statement.function_name}({', '.join([f'i32 %{{{param}}}' for param in statement.parameters])}) {{\n"
