Here is an example of a Prometheus-compatible monitoring stack from scratch in Go:

**Metric Collector**

First, we'll create a simple metric collector that collects metrics from a fictional HTTP endpoint. We'll use the `net/http` package to make requests to the endpoint and the `encoding/json` package to decode the response.

```go
// collector.go
package main

import (
    "encoding/json"
    "fmt"
    "net/http"
    "time"
)

// Metric represents a single metric
type Metric struct {
    Name  string
    Value float64
}

// Collector represents a metric collector
type Collector struct {
    endpoint string
}

// NewCollector returns a new Collector
func NewCollector(endpoint string) *Collector {
    return &Collector{endpoint: endpoint}
}

// Collect collects metrics from the endpoint
func (c *Collector) Collect() ([]Metric, error) {
    resp, err := http.Get(c.endpoint)
    if err != nil {
        return nil, err
    }
    defer resp.Body.Close()

    var metrics []Metric
    err = json.NewDecoder(resp.Body).Decode(&metrics)
    if err != nil {
        return nil, err
    }

    return metrics, nil
}

func main() {
    collector := NewCollector("http://example.com/metrics")
    metrics, err := collector.Collect()
    if err != nil {
        fmt.Println(err)
        return
    }

    for _, metric := range metrics {
        fmt.Printf("%s: %f\n", metric.Name, metric.Value)
    }
}
```

**TSDB Storage**

Next, we'll create a simple TSDB (Time Series Database) storage using a map to store the metrics. We'll use the `sync` package to make the storage thread-safe.

```go
// tsdb.go
package main

import (
    "sync"
    "time"
)

// TSDB represents a Time Series Database
type TSDB struct {
    metrics map[string][]float64
    mutex    sync.RWMutex
}

// NewTSDB returns a new TSDB
func NewTSDB() *TSDB {
    return &TSDB{metrics: make(map[string][]float64)}
}

// AddMetric adds a metric to the TSDB
func (tsdb *TSDB) AddMetric(name string, value float64) {
    tsdb.mutex.Lock()
    defer tsdb.mutex.Unlock()

    tsdb.metrics[name] = append(tsdb.metrics[name], value)
}

// GetMetric returns the metrics for a given name
func (tsdb *TSDB) GetMetric(name string) []float64 {
    tsdb.mutex.RLock()
    defer tsdb.mutex.RUnlock()

    return tsdb.metrics[name]
}

func main() {
    tsdb := NewTSDB()

    // Add some metrics
    tsdb.AddMetric("metric1", 1.0)
    tsdb.AddMetric("metric1", 2.0)
    tsdb.AddMetric("metric2", 3.0)

    // Get the metrics
    metrics := tsdb.GetMetric("metric1")
    for _, metric := range metrics {
        fmt.Printf("%f\n", metric)
    }
}
```

**PromQL-like Query Engine**

Next, we'll create a simple PromQL-like query engine using a parser and an evaluator. We'll use the `github.com/prometheus/promql/parser` package to parse the PromQL queries and the `github.com/prometheus/promql/ast` package to evaluate the queries.

```go
// query_engine.go
package main

import (
    "fmt"
    "github.com/prometheus/promql/ast"
    "github.com/prometheus/promql/parser"
)

// QueryEngine represents a PromQL-like query engine
type QueryEngine struct {
    tsdb *TSDB
}

// NewQueryEngine returns a new QueryEngine
func NewQueryEngine(tsdb *TSDB) *QueryEngine {
    return &QueryEngine{tsdb: tsdb}
}

// Evaluate evaluates a PromQL query
func (qe *QueryEngine) Evaluate(query string) ([]float64, error) {
    expr, err := parser.ParseExpr(query)
    if err != nil {
        return nil, err
    }

    ctx := &ast.EvalContext{}
    ctx.RegisterFunc("metric1", func() float64 { return 1.0 })
    ctx.RegisterFunc("metric2", func() float64 { return 2.0 })

    result, err := expr.Eval(ctx)
    if err != nil {
        return nil, err
    }

    return result, nil
}

func main() {
    tsdb := NewTSDB()
    queryEngine := NewQueryEngine(tsdb)

    // Evaluate a query
    result, err := queryEngine.Evaluate("metric1 + metric2")
    if err != nil {
        fmt.Println(err)
        return
    }

    for _, value := range result {
        fmt.Printf("%f\n", value)
    }
}
```

**Alertmanager**

Finally, we'll create a simple Alertmanager that sends alerts based on the metrics in the TSDB. We'll use the `github.com/prometheus/alertmanager/types` package to define the alert types and the `github.com/prometheus/alertmanager/notifier` package to send the alerts.

```go
// alertmanager.go
package main

import (
    "fmt"
    "github.com/prometheus/alertmanager/notifier"
    "github.com/prometheus/alertmanager/types"
)

// Alertmanager represents an Alertmanager
type Alertmanager struct {
    tsdb *TSDB
}

// NewAlertmanager returns a new Alertmanager
func NewAlertmanager(tsdb *TSDB) *Alertmanager {
    return &Alertmanager{tsdb: tsdb}
}

// Check checks the metrics in the TSDB and sends alerts if necessary
func (am *Alertmanager) Check() {
    // Check the metrics
    metrics := am.tsdb.GetMetric("metric1")
    if len(metrics) > 0 && metrics[0] > 10 {
        // Send an alert
        alert := types.Alert{
            Labels: map[string]string{
                "alertname": "metric1",
            },
            Annotations: map[string]string{
                "summary": "metric1 is high",
            },
        }

        notifier := notifier.NewNotifier()
        err := notifier.Send(alert)
        if err != nil {
            fmt.Println(err)
            return
        }
    }
}

func main() {
    tsdb := NewTSDB()
    alertmanager := NewAlertmanager(tsdb)

    // Check the metrics
    alertmanager.Check()
}
```

To integrate all these components together, you can create a main function that starts the collector, TSDB, query engine, and alertmanager.

```go
// main.go
package main

import (
    "fmt"
    "time"
)

func main() {
    // Create a new TSDB
    tsdb := NewTSDB()

    // Create a new collector
    collector := NewCollector("http://example.com/metrics")

    // Create a new query engine
    queryEngine := NewQueryEngine(tsdb)

    // Create a new alertmanager
    alertmanager := NewAlertmanager(tsdb)

    // Start the collector
    go func() {
        for {
            metrics, err := collector.Collect()
            if err != nil {
                fmt.Println(err)
                return
            }

            for _, metric := range metrics {
                tsdb.AddMetric(metric.Name, metric.Value)
            }

            time.Sleep(10 * time.Second)
        }
    }()

    // Start the query engine
    go func() {
        for {
            query := "metric1 + metric2"
            result, err := queryEngine.Evaluate(query)
            if err != nil {
                fmt.Println(err)
                return
            }

            for _, value := range result {
                fmt.Printf("%f\n", value)
            }

            time.Sleep(10 * time.Second)
        }
    }()

    // Start the alertmanager
    go func() {
        for {
            alertmanager.Check()
            time.Sleep(10 * time.Second)
        }
    }()

    select {}
}
```

This will start the collector, TSDB, query engine, and alertmanager, and they will all run concurrently. The collector will collect metrics from the endpoint, the TSDB will store the metrics, the query engine will evaluate PromQL queries, and the alertmanager will send alerts based on the metrics.
